/**
 * The third-party notices of the app bundle: `public/third-party-notices.json`, generated by
 * `tools/repo-checks/scripts/app_notices.py` (the one source of truth, also checked in CI and by
 * the release gate), bundled by Vite and shown by the About page. This module only validates and
 * counts what the page was given; it never invents a notice.
 */

export const NOTICES_PATH = './third-party-notices.json';

export interface NoticePackage {
  name: string;
  /** The copyright statements as the package states them. */
  copyright: string[];
  /** The content of the package's NOTICE file (Apache-2.0), if it ships one. */
  notice: string | null;
}

export interface NoticeLicence {
  id: string;
  /** The licence text, once per licence. */
  text: string;
  packages: NoticePackage[];
}

export interface Notices {
  licences: NoticeLicence[];
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function nonEmpty(value: unknown): value is string {
  return typeof value === 'string' && value.trim() !== '';
}

function parsePackage(raw: unknown): NoticePackage | null {
  if (!isRecord(raw) || !nonEmpty(raw.name) || !Array.isArray(raw.copyright)) return null;
  const copyright = raw.copyright.filter(nonEmpty);
  if (copyright.length === 0) return null;
  return { name: raw.name, copyright, notice: nonEmpty(raw.notice) ? raw.notice : null };
}

/**
 * Validate the notices file. Returns null for anything that is not a complete notices document
 * (one bad entry makes the whole file unusable: a partial list would look complete).
 */
export function parseNotices(raw: unknown): Notices | null {
  if (!isRecord(raw) || raw.schema !== 1 || !Array.isArray(raw.licences)) return null;
  const licences: NoticeLicence[] = [];
  for (const entry of raw.licences) {
    if (!isRecord(entry) || !nonEmpty(entry.id) || !nonEmpty(entry.text)) return null;
    if (!Array.isArray(entry.packages) || entry.packages.length === 0) return null;
    const packages: NoticePackage[] = [];
    for (const item of entry.packages) {
      const parsed = parsePackage(item);
      if (!parsed) return null;
      packages.push(parsed);
    }
    licences.push({ id: entry.id, text: entry.text, packages });
  }
  return licences.length > 0 ? { licences } : null;
}

export function packageCount(notices: Notices): number {
  return notices.licences.reduce((sum, licence) => sum + licence.packages.length, 0);
}

/** Fetch and validate the bundled file; null when it is missing or malformed. */
export async function loadNotices(fetchJson: () => Promise<unknown>): Promise<Notices | null> {
  try {
    return parseNotices(await fetchJson());
  } catch {
    return null;
  }
}
